contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 value) public payable {
        uint256 beforeTD = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 beforeBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(value <= beforeBal);

        c.burn(value); if (__ESBMC_reverted()) return;

        uint256 afterTD = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(afterTD == beforeTD - value);
    }

    receive() external payable {}
}

